import React from "react";
import "./page.css";

const Contacts = () => {
  return (
    <section className="page">
      <h1 className="title">Contacts</h1>

      <div className="contacts-block">
        <p>Email: example@mail.com</p>
        <p>Phone: +996 555 555 555</p>

        <div className="socials">
          <a href="https://instagram.com/твой_ник" target="_blank" rel="noreferrer">
            <img src="/img/icons/instagram.svg" alt="Instagram" />
          </a>
          <a href="https://wa.me/твой_номер" target="_blank" rel="noreferrer">
            <img src="/img/icons/whatsapp.svg" alt="WhatsApp" />
          </a>
          <a href="https://t.me/твой_ник" target="_blank" rel="noreferrer">
            <img src="/img/icons/telegram.svg" alt="Telegram" />
          </a>
        </div>
      </div>
    </section>
  );
};

export default Contacts;
